# All statistics are taken unchanged from experiments E1-E7 (see Chapter 10).

TITLE = 'DhanVeda: Research and Experimental Analysis Report'
SUBTITLE = 'An evidence-based evaluation of a multi-provider LLM platform for Indian retail investors'

ABSTRACT = [
 ('P', 'Retail participation in Indian equities has expanded rapidly, yet the capacity of individual investors to interpret financial data has not kept pace. DhanVeda (deployed under the name ArthaSift) is an AI decision-support platform built to narrow this gap. It is implemented in Next.js 15 with a Neon Postgres database and exposes 14 AI-assisted features. Every feature is routed through a five-tier hierarchy of large language model (LLM) providers, and a rule-based Environmental, Social and Governance (ESG) engine scores a universe of 532 NSE and BSE securities.'),
 ('P', 'This report evaluates the platform as a research artefact. A review of twelve sources identifies the open problems in LLM-based financial analysis. Seven research hypotheses were fixed in advance and tested through seven reproducible offline experiments on the unmodified source code, totalling more than 5.4 million scoring operations. The experiments cover token budgets for 13 production prompts, ESG tiering of all 532 securities, a 10,000-draw Monte Carlo study of governance-data uncertainty, a 20,000-company simulation of the scoring rubric and a 60,000-run repeated-measurement noise trial.'),
 ('P', 'Three results stand out. First, the compressed scoring prompt reduces input from 3,645 to 1,571 tokens (a 56.9% reduction), bringing a complete call to 4,071 tokens against a 6,000 tokens-per-minute free-tier limit that the uncompressed version (6,145 tokens) exceeds. Second, sector membership explains 96.4% of the variance in the ESG composite, and 46.4% of securities change tier when the governance score moves by a single point. Third, 10% noise in retrieved data moves 62.4% of simulated companies across a verdict band within ten repeated runs. Two hypotheses are supported, four are rejected and one awaits a live trial, which is fully specified. The report closes with ranked recommendations and directions for future research.'),
 ('P', '**Keywords:** large language models; financial analysis; LLM routing; prompt compression; tokenization; ESG scoring; Indian equity market; reproducibility; investor protection.'),
]

KEYFINDINGS = [
 'Prompt compression cut the core analysis prompt by 56.9% (3,645 to 1,571 tokens) without removing any scoring rule.',
 'The platform\'s 4-characters-per-token estimate undercounts number-dense prompts by up to 34.2%.',
 'Sector alone explains 96.4% of ESG composite variance (eta-squared = 0.964).',
 '247 of 532 securities (46.4%, 95% CI 42.2-50.7%) change ESG tier under a one-point governance shift.',
 'At 10% retrieval noise, 62.4% of companies change verdict band across ten runs; mean SD = 3.71 points.',
 'A company at the Indian median on every KPI scores 68, while the simulated population median is 39; the rubric anchor is 50.',
 'Cascade availability reaches 99.990% at a 10% per-tier failure rate, assuming independent failures.',
]

