  ['H2', 'Compressed and full rubrics agree within 3 points', 'Not yet tested', 'Live trial P1 specified'],
  ['H3', 'Repeated runs stable (SD <= 2; >= 90% unchanged band)', 'Not supported (simulated)', 'SD 2.56 and 42.5% band changes at 5% noise (E6)'],
